{"lesson": "The channel is the sum of main and other total_changes, and the put operation is INSERT OR REPLACE with an AFTER INSERT trigger that logs one row per successful insert. The trigger fires on every successful insert, including replacements, so the channel counts each put as 2 (one for the item table, one for the log). Updates and deletes do not fire the trigger. The committed state is the final state after all actions, with rollback undoing uncommitted changes.", "scope": "Predicts channel, committed_count, and committed_sum for any action sequence using the inferred source model: INSERT OR REPLACE with AFTER INSERT trigger, channel = main total_changes + other total_changes.", "source": "def investigate(context, acquire):
    history = acquire("history")
    # Infer put behavior and trigger presence from history
    # We'll simulate all possible combinations and filter by history
    # Family: put in {ignore, replace, upsert}, trigger in {none, after_insert}, channel in {changes, total_main, total_both}

    def simulate(actions, put_mode, trigger, channel_mode):
        # State: items dict, log count, main_total, other_total, changes_main, changes_other
        items = {}
        log_count = 0
        main_total = 0
        other_total = 0
        changes_main = 0
        changes_other = 0
        in_tx_main = False
        in_tx_other = False
        tx_items = None
        tx_log = None
        tx_main_total = 0
        tx_other_total = 0
        tx_changes_main = 0
        tx_changes_other = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            key = act.get("key")
            val = act.get("value")

            if op == "begin":
                if conn == "main":
                    in_tx_main = True
                    tx_items = dict(items)
                    tx_log = log_count
                    tx_main_total = main_total
                    tx_other_total = other_total
                    tx_changes_main = changes_main
                    tx_changes_other = changes_other
                else:
                    in_tx_other = True
                    tx_items = dict(items)
                    tx_log = log_count
                    tx_main_total = main_total
                    tx_other_total = other_total
                    tx_changes_main = changes_main
                    tx_changes_other = changes_other
            elif op == "commit":
                if conn == "main":
                    in_tx_main = False
                else:
                    in_tx_other = False
                tx_items = None
                tx_log = None
            elif op == "rollback":
                if conn == "main":
                    in_tx_main = False
                    if tx_items is not None:
                        items = tx_items
                        log_count = tx_log
                        main_total = tx_main_total
                        other_total = tx_other_total
                        changes_main = tx_changes_main
                        changes_other = tx_changes_other
                else:
                    in_tx_other = False
                    if tx_items is not None:
                        items = tx_items
                        log_count = tx_log
                        main_total = tx_main_total
                        other_total = tx_other_total
                        changes_main = tx_changes_main
                        changes_other = tx_changes_other
                tx_items = None
                tx_log = None
            elif op == "put":
                # Determine if this connection is in a transaction
                in_tx = in_tx_main if conn == "main" else in_tx_other
                # Work on a copy if in transaction
                if in_tx:
                    cur_items = dict(items)
                    cur_log = log_count
                else:
                    cur_items = items
                    cur_log = log_count

                # Apply put based on put_mode
                changed = False
                if key in cur_items:
                    if put_mode == "ignore":
                        changed = False
                    elif put_mode == "replace":
                        cur_items[key] = val
                        changed = True
                    elif put_mode == "upsert":
                        cur_items[key] = val
                        changed = True
                else:
                    cur_items[key] = val
                    changed = True

                if changed:
                    # Trigger fires on successful insert (including replace)
                    if trigger == "after_insert":
                        cur_log += 1
                    # Update counters
                    if conn == "main":
                        changes_main += 1
                        main_total += 1
                        if trigger == "after_insert":
                            main_total += 1
                    else:
                        changes_other += 1
                        other_total += 1
                        if trigger == "after_insert":
                            other_total += 1

                if in_tx:
                    items = cur_items
                    log_count = cur_log
                else:
                    items = cur_items
                    log_count = cur_log
            elif op == "update":
                in_tx = in_tx_main if conn == "main" else in_tx_other
                if in_tx:
                    cur_items = dict(items)
                else:
                    cur_items = items
                if key in cur_items:
                    cur_items[key] = val
                    if conn == "main":
                        changes_main += 1
                        main_total += 1
                    else:
                        changes_other += 1
                        other_total += 1
                if in_tx:
                    items = cur_items
            elif op == "delete":
                in_tx = in_tx_main if conn == "main" else in_tx_other
                if in_tx:
                    cur_items = dict(items)
                else:
                    cur_items = items
                if key in cur_items:
                    del cur_items[key]
                    if conn == "main":
                        changes_main += 1
                        main_total += 1
                    else:
                        changes_other += 1
                        other_total += 1
                if in_tx:
                    items = cur_items

        # Compute channel
        if channel_mode == "changes":
            channel = changes_main
        elif channel_mode == "total_main":
            channel = main_total
        elif channel_mode == "total_both":
            channel = main_total + other_total
        else:
            channel = 0

        committed_count = len(items)
        committed_sum = sum(items.values())
        return channel, committed_count, committed_sum

    # Filter possible models by history
    put_modes = ["ignore", "replace", "upsert"]
    triggers = ["none", "after_insert"]
    channel_modes = ["changes", "total_main", "total_both"]

    possible = []
    for pm in put_modes:
        for tr in triggers:
            for cm in channel_modes:
                ok = True
                for rec in history:
                    ch, cc, cs = simulate(rec["actions"], pm, tr, cm)
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    possible.append((pm, tr, cm))

    if not possible:
        return {"value": None, "unresolved": True}

    # Predict for query
    goal = context.get("goal")
    actions = context.get("actions", [])

    predictions = set()
    for pm, tr, cm in possible:
        ch, cc, cs = simulate(actions, pm, tr, cm)
        if goal == "channel":
            predictions.add(ch)
        elif goal == "committed_count":
            predictions.add(cc)
        elif goal == "committed_sum":
            predictions.add(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(predictions) == 1:
        return {"value": predictions.pop(), "unresolved": False}
    else:
        return {"value": None, "unresolved": True}
"}
